import logging

from ute_ue.config import loggers as ute_ue_logging
from ta_ue_plugin_ultracaller.exceptions import UltraCallerTestPhaseException, UltraCallerTestNotRunning


class UcTestSequence(object):
    """Implementation of generic UltraCaller test sequence"""

    def __init__(self, test_sequence_name, configuration, uc_connection, logger_name='ute_ue'):
        """
        Initialization of UltraCaller test sequence
        :param test_sequence_name:
        :param configuration:
        :param uc_connection:
        :param logger_name:
        """
        self._uc_connection = uc_connection
        self._configuration = configuration
        self.test_sequence_name = test_sequence_name
        self._test_sequence_id = None
        self._running = False

        if 'ue_logger_name' in self._configuration:
            raw_logger = logging.getLogger(self._configuration['ue_logger_name'])
        else:
            raw_logger = logging.getLogger(logger_name)
        self.logger = ute_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'ULTRACALLERTEST'})

    def start(self):
        """
        Start UltraCaller test sequence
        :return:
        :raises: UltraCallerTestPhaseException if not started within timeout
        """
        self.logger.info('Starting UltraCaller test sequence "{}"'.format(self.test_sequence_name))

        response = self._uc_connection.start_test_sequence(imei=self._configuration['imei'],
                                                           test_sequence_name=self.test_sequence_name)
        self._test_sequence_id = response['data'][0]['testSequenceId']

        if self._uc_connection.wait_until_test_sequence_phase(test_sequence_id=self._test_sequence_id,
                                                              phase='running'):
            self._running = True
            self.logger.info('Started UltraCaller test sequence "{}"'.format(self.test_sequence_name))
        else:
            self.logger.error('UltraCaller test sequence "{}" FAILED to start within time limit'.format(self.test_sequence_name))
            raise UltraCallerTestPhaseException('running')

    def stop(self):
        """
        Stop UltraCaller test sequence
        :return:
        :raises: UltraCallerTestPhaseException if not stopped within timeout
        """
        self.logger.info('Stopping UltraCaller test sequence "{}"'.format(self.test_sequence_name))

        if not self._running:
            self.logger.debug('UltraCaller test sequence "{}" has already stopped'.format(self.test_sequence_name))
            return

        self._uc_connection.stop_test_sequence(imei=self._configuration['imei'], test_sequence_id=self._test_sequence_id)
        if self._uc_connection.wait_until_test_sequence_phase(test_sequence_id=self._test_sequence_id,
                                                              phase='completed'):
            self._running = False
        else:
            self.logger.error('UltraCaller test sequence "{}" FAILED to stop within time limit'.format(self.test_sequence_name))
            raise UltraCallerTestPhaseException('completed')

    def get_status(self):
        """
        Get status of UltraCaller test sequence
        :return: List of dictionaries
        """
        response = self._uc_connection.test_sequence_status(test_sequence_id=self._test_sequence_id)
        return response['data']

    def get_results(self):
        """
        Get results of UltraCaller test sequence
        :return: List of dictionaries
        """
        response = self._uc_connection.get_test_sequence_result(test_sequence_id=self._test_sequence_id)
        # TODO: We could sort here with timestamp since server gives data in random order
        # This would be easier for testers
        return response['data']

    def await_finish(self, timeout=0):
        """
        Waits until this uc test sequence finishes.
        No action if given uc test is already finished.
        :param timeout: Timeout in seconds, 0=forever
        :raises: UltraCallerTestNotRunning if test is not running
        :raises: UltraCallerTestPhaseException if UC UE fails to finish within time limit
        :return: None
        """
        if not self._running:
            raise UltraCallerTestNotRunning(self.test_sequence_name)

        if int(timeout) == 0:
            timeout = 43200  # 12 hours

        if self._uc_connection.wait_until_test_sequence_phase(test_sequence_id=self._test_sequence_id,
                                                              phase='completed', wait_time=int(timeout)):
            self._running = False
        else:
            self.logger.error('UltraCaller test sequence "{}" FAILED to stop within time limit'.format(self.test_sequence_name))
            self.stop()
            raise UltraCallerTestPhaseException('completed')
